// HTTP请求到MySQL端口的结果分析
if (msg.statusCode) {
    if (msg.statusCode >= 200 && msg.statusCode < 500) {
        msg.payload = {
            status: "✅ 网络连通",
            message: "Node-RED可以访问iot-mysql容器",
            host: "iot-mysql",
            port: 3306,
            httpStatus: msg.statusCode,
            note: "HTTP响应说明MySQL端口可达"
        };
    } else {
        msg.payload = {
            status: "⚠️ 网络连通但服务异常",
            message: "可以访问容器但MySQL服务可能有问题",
            httpStatus: msg.statusCode
        };
    }
} else if (msg.error) {
    if (msg.error.code === 'ECONNREFUSED') {
        msg.payload = {
            status: "❌ 连接被拒绝",
            message: "MySQL容器未启动或端口未开放",
            error: msg.error.message
        };
    } else if (msg.error.code === 'ENOTFOUND') {
        msg.payload = {
            status: "❌ DNS解析失败",
            message: "无法解析iot-mysql主机名",
            error: msg.error.message
        };
    } else {
        msg.payload = {
            status: "❌ 网络错误",
            message: "其他网络连接问题",
            error: msg.error.message,
            errorCode: msg.error.code
        };
    }
} else {
    msg.payload = {
        status: "⚠️ 未知状态",
        message: "HTTP请求没有返回预期结果",
        response: msg.payload
    };
}
return msg;

// 准备最基础的MySQL连接测试
msg.topic = "SELECT 'Connection Test' as message, NOW() as timestamp";
msg.payload = {
    host: "iot-mysql",
    port: 3306,
    user: "root",
    password: "iot123456",
    database: "IoTDataCollection_Main"
};
return msg;

// 分析MySQL查询结果
if (msg.payload && Array.isArray(msg.payload) && msg.payload.length > 0) {
    const result = msg.payload[0];
    msg.payload = {
        status: "✅ MySQL连接成功",
        message: "数据库连接和查询正常",
        connection: "Node-RED ↔ MySQL 连接正常",
        queryResult: result,
        timestamp: new Date().toISOString()
    };
} else if (msg.error) {
    msg.payload = {
        status: "❌ MySQL连接失败",
        message: "数据库连接或查询失败",
        error: msg.error.message || msg.error,
        errorCode: msg.error.code,
        timestamp: new Date().toISOString()
    };
} else {
    msg.payload = {
        status: "⚠️ MySQL查询异常",
        message: "查询没有返回预期结果",
        response: msg.payload,
        timestamp: new Date().toISOString()
    };
}
return msg;

// 获取Node-RED容器的环境信息
msg.payload = {
    nodeRedInfo: {
        hostname: msg.req ? msg.req.hostname : 'localhost',
        timestamp: new Date().toISOString(),
        timezone: Intl.DateTimeFormat().resolvedOptions().timeZone
    },
    mysqlConnection: {
        expectedHost: "iot-mysql",
        expectedPort: 3306,
        expectedDatabase: "IoTDataCollection_Main",
        expectedUser: "root"
    },
    networkTest: {
        message: "容器间通信测试准备就绪",
        testOrder: [
            "1. HTTP端口测试 - 验证网络层连通性",
            "2. MySQL直连测试 - 验证数据库层连接"
        ]
    }
};
return msg;
